"""Invoices: priced bookings -> invoices (CONTRACT.md)."""

__all__ = ["make"]

VAT_PCT = 5


def make(booking):
    if "price_cents" not in booking:
        raise ValueError("booking is not priced")
    net = booking["price_cents"]
    vat = (net * VAT_PCT * 2 + 100) // 200
    return {"id": booking["id"], "lines": [{"label": "mooring", "cents": net}, {"label": "vat", "cents": vat}], "total_cents": net + vat}

