"""Slot allocation: priced bookings -> bookings with a slot (CONTRACT.md)."""
from datetime import datetime, timedelta

__all__ = ["assign"]

SLOTS = [80, 80, 120, 120, 170, 170, 260, 260, 300]  # length in dm that each berth takes, berth 1 first
FMT = "%Y-%m-%dT%H:%M"


def assign(bookings):
    busy = [[] for _ in SLOTS]
    out = []
    for b in sorted(bookings, key=lambda b: (b["arrive_utc"], b["id"])):
        start = datetime.strptime(b["arrive_utc"], FMT)
        end = start + timedelta(days=b["nights"])
        for i, size in enumerate(SLOTS):
            if size >= b["length_dm"] and all(end <= s or start >= e for s, e in busy[i]):
                busy[i].append((start, end))
                out.append({**b, "slot": i + 1})
                break
        else:
            raise ValueError("no berth for " + b["id"])
    return out

