__all__ = ["price"]

BANDS = [(80, 2500), (120, 3500), (170, 6100), (None, 7600)]  # (longest length in dm that is still in the band, cents per night); None = no limit
LONG_STAY_NIGHTS = 5
PCT = 12


def _rate(length_dm):
    for upto, cents in BANDS:
        if upto is None or length_dm <= upto:
            return cents


def price(booking):
    if "length_dm" not in booking:
        raise ValueError("booking has no length")
    base = _rate(booking["length_dm"]) * booking["nights"]
    if booking["nights"] >= LONG_STAY_NIGHTS:
        base -= (base * PCT * 2 + 100) // 200
    return {**booking, "price_cents": base}

